    "kanji": "雨",
    "han_viet": "Vũ",
    "nghia": "mưa",
    "on": "ウ",
    "kun": "あめあまさめ",
    "page": 11,
    "jlpt": "N5-N4",
    "chi_tiet": "Chữ VŨ 雨 (mưa) là một chữ tượng hình. Dạng ban đầu gồm nét ngang trên cùng là biểu trưng của mây trên trời. Bên dưới là hình ảnh những giọt nước mưa, chia làm ba hàng, khoảng cách đều đặn. Với tính ước lệ, ba là số nhiều, ba hàng nước mưa rơi xuống từ trên tầng không là biểu tượng của vô số những giọt nước. Đến dạng chữ triện văn, khoảng không gian giữa trời và mây đã được thể hiện riêng biệt. Dưới bầu trời là mây, dưới mây là những giọt nước nối nhau thành dòng rơi xuống. Theo tác giả Đường Hán, trong số hơn một vạn hiện vật bằng mai rùa và xương thú có ghi nhũng lời hào (lời của quẻ bói trong chu dịch) thì có đến hàng ngàn lời nói liên quan đến mưa. Điều đó chứng tỏ từ thời nhà Thương, người ta đã rất chú ý đến việc quan sát thiên văn. Các hiện tượng mưa gió, sấm chớp được quan tâm khám phá. Việc nghiên cứu về mưa gắn liền với nông nghiệp canh tác và đời sống. 532 Nhóm biên soạn: https://www.facebook.com/vuihocchuhan/ Ngoài vai trò là chữ đơn ra chữ VŨ còn là bộ thủ đóng vai trò tạo chữ, đa số là dùng để biểu nghĩa. Những chữ hán có bộ VŨ cấu thành thường liên quan đến các hiện tượng tự nhiên như mây, mưa, sương,…như các chữ SƯƠNG 霜 VÂN 雲.",
