    "page": 11,
    "jlpt": "N5-N4",
    "chi_tiet": "Chữ TỬ 子 là một chữ tượng hình, vẽ lại một cách đơn giản nhất đữa trẻ vừa lột lòng mẹ. Quan sát hình hài những đứa trẻ sơ sinh, ta thấy, chúng đều đầu to, mình nhỏ. Hai cánh tay giơ lên như đang cử động. Hai chân sở dĩ không tích ra là vì trẻ sơ sinh thường được quấn trong một mảnh vải để giữ ấm cho phần bụng và chân. Sự phát họa đó rất phù hợp với hình dạng ban đầu của trẻ sơ sinh. Với hình thể ban đầu như vậy, trẻ con không thể không có sự che chở nuôi nấng của cha mẹ mà trưởng thành được. Chúng phải có cái ăn để tồn tai, đồng thời phải được giáo dục để phát triển trí tuệ. Chính vì thế chữ TỬ 子 thêm bộ MIÊN 宀 (mái nhà) thành chữ TỰ 字 (chữ). Cách đọc TỬ 子 và TỰ 字 gần giống nhau. Những bậc làm cha mẹ luôn lo lắng cho con cái mình được ăn, được học, ngược lại, đạo làm con phải nhớ công ơn dưỡng dục của cha mẹ.",
