    "jlpt": "N5-N4",
    "chi_tiet": "Chữ HỒI 回 ở cổ văn (giáp cốt, kim văn) là một chữ tượng hình miêu tả lại một vòng xoáy. Vòng xoáy này sau đó được thay thế bằng hai hình vuông lớn nhỏ lồng vào nhau bắt đầu từ thể triện văn.",
