    "jlpt": "N5-N4",
    "chi_tiet": "Chữ THỂ 体 là một chữ hội ý kết cấu trái phải, được cấu tạo bởi bộ NHÂN 人 (con người) và BẢN 本 (gốc, cơ sở). Cơ thể con người là cơ sở của một con người, nó là điểm kết nối chung của cả đầu tay và chân. 体 là biến thể của 體, cả hai đều có chung ý nghĩa và cách phát âm, cả hai được dùng song song với nhau.",
