    "chi_tiet": "Chữ viết, văn vẻ, dấu 文 DẠNG KHÁC PHIÊN ÂM wén • wèn Kun: ふみあや ÂM KUN/ON On: ブンモン án văn 案文 • bất thành văn 不成文 • chánh văn 正文 • TỪ GHÉP cổ văn 古文 • công văn 公文 • diễn văn 演文. Chữ VĂN 文 là một chữ tượng hình, mô tả một người đàn ông có hình xăm trên cơ thể (cũng có thể hiểu là họa tiết, hoa văn được thêu trên trang phục), ý nghĩa ban đầu của nó là hoa văn và thiết kế, nhưng ý nghĩa như vậy đã được thay thế bằng 紋. Mặt khác, vì hán tự (ký tự Trung Quốc) được phát triển từ hình ảnh, nên 文 được sử dụng để thể hiện biểu tượng chữ viết trong giao tiếp của con người.",
