    "page": 11,
    "jlpt": "N5-N4",
    "chi_tiet": "Chữ PHƯƠNG 方 là một chữ hội ý, trong giáp cốt văn mô tả một phạm nhân đeo trên cổ một chiếc gông. Chiếc gông ở Trung Quốc cổ đại thường có hình vuông, nên chữ có nghĩa là hình vuông hay chữ nhật, các cạnh của hình vuông ở bốn hướng khác nhau nên 方 cũng có nghĩa là phía, hướng. Ngoài ra, những phạm nhân này sẽ bị đày đi đến một nơi xa xôi như biên ải hay vùng hẻo lánh nào đó. Nên chữ 方 còn có nghĩa là nơi xa xôi, phương xa.",
