    "page": 11,
    "jlpt": "N5-N4",
    "chi_tiet": "Chữ Minh 明 nghĩa là sáng, được hợp bởi bộ Nhật 日 là mặt trời và bộ Nguyệt 月 là mặt trăng. Nhật và nguyệt hai vầng sáng lớn nhất trên bầu trời theo quan niệm của người xưa, khi hai vầng sáng này hội tụ lại sẽ tạo nên một vàng sáng lớn hơn, cho nên ý nghĩa ban sơ của chữ Minh 明 là sáng , chiếu sáng, sau phát triển thêm nghĩa mở rộng chỉ những người thông minh và hiểu biết.",
