    "chi_tiet": "Chữ KÝ 記 là một chữ dạng hình thanh kiêm hội ý. Bao gồm bộ NGÔN 言 (lời nói hay ngôn từ) và KỶ 己 (hình ảnh của một sợi dây cuộn, xem lại bài chữ 己). Người Trung Quốc cổ đại đã tạo ra các bản ghi bằng cách buộc các nút thắt, bộ 言 là lời nói, ngôn từ, là công cụ để giao tiếp, vì vậy 記 ban đầu có ý nghĩa là các bản ghi, ghi lại các câu chuyện trong cuộc sống.",
