    "jlpt": "N3-N2",
    "chi_tiet": "Chữ Quan 官 là chữ hội ý kết cấu trên dưới, phần trên là bộ miên, là biểu tượng của mái nhà. Phần dưới là chữ Phụ 峊,chữ 峊 trong giáp cốt văn hình dạng giống như bậc đá trên vách núi cao, dùng biểu thị địa thế) phát triển thành nghĩa là gò đất là điểm dừng chân khi người ta leo núi để đi săn bắt và hái lượm. Đường Hán cho rằng, người xưa, trongquá trình xa nhà đi săn bắn chủ yếu dựa vào đôi chân, khi mỏi gối chồn chân thì cần có điểm dừng. Chữ Quan vốn cũng có nghĩa là túp lều tạm làm nơi dừng chân nghỉ ngơicủa người dân trên đường đi săn bắn. Sau đó phát triển nghĩa thành lều trại dã chiến, và sau đó tiếp tục phát triển thành quan phủ, quan chức.. Trong Tân hiện đại Hán ngữ từ điển giải thích, quan là một chữ hội ý , gồm miên (nhà) phần dưới có nghĩa là đông người. Tính chất hội ý đó thể hiện ý nghĩa là nơi quản lý dân, nghĩa gốc là quan phủ, là nơi làm việc công.",
