    "lesson": 5,
    "page": 52,
    "jlpt": "N3-N2",
    "chi_tiet": "Chữ phu (夫, chồng) tương đối phức tạp hơn so với chữ Thê (妻). Chữ phu được tạo bởi chữ đại (大) và chữ nhất (一). Chữ nhất (一) trong “Thuyết văn giải tự” mang ý nghĩa là đạo sinh ở nhất, phân chia trời đất, hóa thành vạn vật, là ngọn nguồn của vạn vật thiên địa, là ngọn nguồn và đạo lý căn bản. Còn chữ đại (大) là hình tượng một người đứng thẳng chính diện. Một người đứng thẳng, bên trên lại có chữ nhất thì chứng tỏ trách nhiệm của người này không thể nhỏ được. Cho nên, phu (người chồng) là phải có trách nhiệm gánh vác, phải giữ vai trò chủ đạo trong gia đình. Điều mà người ta vẫn gọi là “phu xướng phụ tùy”, người chồng đề xướng thì vợ thuận theo, nhưng đương nhiên không phải là đề xướng một cách tùy tiện, tùy ý mà phải phù hợp đạo lý.",
