    "chi_tiet": "Chữ Thị (“示”) nằm bên trái của chữ Thân. Ngày nay, nó thường được viết thành “礻”, có nghĩa là bảo cho biết, mách cho biết. Từ ý nghĩa ấy, nó tượng trưng cho sự điểm hóa, gợi ý và khai thị của Trời đất và Thần đối với con người thế gian. Bên phải của chữ “Thần” là chữ Thân (“申”), nó vốn là chữ gốc của chữ Thần 410 Nhóm biên soạn: https://www.facebook.com/vuihocchuhan/ (“神”). Trong một lý giải khác, chữ Thân (“申”) là chỉ các tia chớp của ngày mưa, nó biến hóa không ngừng. Khi chữ Kim Văn kế tục chữ Giáp Cốt thì có loại chữ Kim Văn viết chữ Thân (“申”) dưới hình dạng của đôi bàn tay, dựng thẳng đứng để biểu thị rằng Thần nắm trong tay hết thảy.",
