    "page": 84,
    "jlpt": "N3-N2",
    "chi_tiet": "Chữ MIÊN là chữ hội ý gồm hai bộ thủ tạo thành. Trong đó có bộ MỊCH 糸 (sợi tơ) và chữ BẠCH 帛 (lụa) tạo thành, nghĩa là tơ lụa được chế tác từ bông. Chữ MIÊN 棉 (cây bông) cùng âm cũng là chữ hội ý kết cấu trái phải, gồm bộ MỘC 木 và bộ BẠCH 帛 tạo thành. Bông là nguyên liệu dệt quan trong nhất và cũng thường gặp nhất. Nhưng nó vốn là một loại thực vất nhiệt đới. Trước nhà hán, bông đươc đưa từ các nước châu phi, ấn độ đến các vùng biên giới Trung Quốc như đảo Hải Nam, Vân Nam. Cho đến đời tống , nguyên bông mới được mở rộng sang khu vực Trung Nguyên. Trong các nguyên liệu dệt của Trung Quốc, bông ra đời khá muộn. Một số 257 Nhóm biên soạn: https://www.facebook.com/vuihocchuhan/ sách cổ ghi rằng, loại tơ rối được lấy ra từ bề mặt kén tằm, sau khi được xử lý thành dạng bông. Nó có thể may các đồ chống rét chứ không phải nguyên liệu dệt. Hình dáng của hoa cây bông rất giống bông cho nên người ta cũng gọi 棉 Là miên (bông). Sau đời hán người ta phân biệt nó với bông tơ và tạo thành chữ 棉 MIÊN (bông).",
