    "jlpt": "N3-N2",
    "chi_tiet": "Chữ TÀI 材 về cấu tạo là một chữ hình thanh kết cấu trái phải, bao gồm bên trái là chữ MỘC 木 (cây cối) có nhiệm vụ biểu diễn nghĩa và bộ TÀI 才(tài giỏi) có tác dụng biểu thị âm đọc. MỘC là gỗ 木, trong hoạt động sản xuất của người Hán xưa, cây cối ngoài vai trò cung cấp lương thực thông qua hái lượm hoặc trồng trọt, cây cối còn cung cấp vật liệu, phục vụ xây dựng và chế tạo vũ khí. Chữ TÀI 材 với MỘC 木 là thành phần biểu nghĩa, biểu thị cho những thứ có liên quan đến vật liệu gỗ từ thiên nhiên.",
