    "lesson": 11,
    "page": 88,
    "jlpt": "N3-N2",
    "chi_tiet": "Chữ PHẤN 粉 trong từ điển hán ngữ hiện đại được định nghĩa vừa là chữ hình thanh vừa là chữ hội ý. Nếu là chữ hình thanh thì chữ PHẤN cấu tạo bởi hai bộ là MỄ 米 (lúa gạo) và chữ PHÂN 分 (phân chia). Trong đó, MỄ 米 có nhiệm vụ biểu thị ý nghĩa chính của chữ, chữ PHÂN 分 có tác dụng chỉ âm đọc. Còn nếu là chữ hội ý thì tính chất hội ý của hai bộ phận tạo chữ này là chỉ việc hạt gạo được xay nghiền thành những hạt nhỏ mịn hơn. Từ xa xưa, người nông dân đã biết dùng cối xay sử dụng sức người hoặc trâu bò để nghiền nhỏ hạt gạo, biến chúng thành thứ bột mịn, để từ đó dễ dàng chế biến sang các dạng thực phẩm khác, phục vụ nhu cầu rất đa dạng về ẩm thực của con người. Chữ PHẤN 粉 từ nghĩa chỉ bột, cám gạo phát triển thành nghĩa chỉ cho tất cả các loại hạt nhỏ mịn như ngày nay.",
