    "chi_tiet": "Chữ CỐ 固 (kiên cố), về mặt cấu tạo là một chữ hình thanh kết cấu trong ngoài. Bên ngoài là chữ VI 囗 (bao vây) là bộ phận biểu ý, bên trong là chữ CỔ 古(cũ , xưa) có tác dụng biểu âm. Chữ Cố liên quan đến chiến thuật phòng ngự của quân đội trung quốc xưa. Khi chinh phạt được một vùng đất nào đó, công việc đầu tiên của các quân vương là xây thành, đắp lũy, nhằm mục đích bảo vệ người dân, tránh sự xâm hại từ bên ngoài vào. Thành lũy được xây dựng bằng nhiều lớp, trên lại có lính canh gác nên được xem là rất kiên cố. Trong chữ CỐ bộ VI 囗 là bộ phận tạo nghĩa, 囗 là biểu tượng của tường thành vững chắc, kết hợp với âm đọc của chữ CỔ 古 tạo thành chữ 固 với nghĩa là kiên cố, vững chắc.",
