    "chi_tiet": "Chữ 包 được viết ở dạng chữ cổ là hình một đứa trẻ đang nằm trong bào thai của người mẹ. Thân hình đứa trẻ cuộn tròn lại với một dây rốn ở phía dưới. Sau qua trình phát triển, đến sau này hình ảnh bào thai được thay bằng bộ BAO 勹 còn cơ thể đứa trẻ được viết bằng chữ TỊ 巳, tính chất hội ý vẫn giữ nguyên, thể hiện một đứa trẻ trong bào thai. Từ nghĩa chỉ bào thai lúc ban đầu, chữ 包 mở rộng nghĩa thành túi, gói, bao, vây quanh, đảm bảo.",
