    "lesson": 11,
    "page": 91,
    "jlpt": "N3-N2",
    "chi_tiet": "Chữ THƯƠNG 商 là một chữ hội ý kết cấu trong ngoài. Bên ngoài là phần đầu của chữ BÀNG 旁 (bên cạnh), với hàm ý: người kinh doanh đã không phải là người sản xuất lại càng không phải người tiêu dùng, mà là người đứng bên ngoài nhìn nhận. Tuy nhiên, người ngoài đánh giá nhìn nhận sự vật sẽ mang tính khách quan hơn, không chịu tác động của yếu tố chủ quan. Phần bên trong của chữ THƯƠNG 商 có sự kết hợp của chữ BÁT 八 và KHẨU 口 hai chữ này hội ý lại có nghĩa là nói nhiều, nói giỏi. Người kinh doanh phải nói giỏi, nói giỏi là một kỹ xảo của người kinh doanh. Như thế mới thuyết phục được người sản xuất và người tiêu dùng, nhắm đến mục đích cuối cùng là nhập được hàng và bán được hàng.",
