    "lesson": 13,
    "page": 101,
    "jlpt": "N3-N2",
    "chi_tiet": "Chữ TỬ 子 (con) ghép với chữ HỆ 系 (sợi dây, nối tiếp) thành chữ TÔN 孫 (cháu) ở dạng phổn thể. Con cháu là thế hệ kế tiếp, kế thừa và phát triển sự nghiệp của cha ông, làm cho gia đình, xã hội được phát triển, ngày càng phồn vinh. Cha mẹ sinh ra con. Con lại sinh ra cháu. Dòng dõi được nối tiếp từ thế hệ này thế hệ khác. Chữ giản thể thay chữ HỆ 系 bằng chữ TIỂU 小 (nhỏ). Đương nhiên cháu phải nhỏ hơn con, vị thế cũng thấp hơn. Điều đó cũng chứng tỏ quan niệm của người trung Quốc về gia đình. Gia đình là tế bào của xã hội. Trong gia đình, con cháu là thế hệ nối tiếp, trên dưới có trật tự, có lề lối gia phong, làm cho giống nòi được mãi mãi sinh sôi, cũng là sợi day gắn kết, gắn bó tình cảm con cháu, cha mẹ, ông bà ngày càng bền chặt.",
