    "lesson": 13,
    "page": 101,
    "jlpt": "N3-N2",
    "chi_tiet": "Chữ 君 Quân là một chữ hội ý kết cấu trên dưới, phẩn trên là biếu tượng cùa bàn tay cầm quyền (chữ 尹 Doãn cũng có nghĩa là cai trị), nét phẩy là biểu tượng của ngọn roi, cũng chính là quyền lực uy phong, tri thức và phẩm hạnh của đấng minh quân giữ trọng trách trị vì thiên hạ. Bộ 口 (miệng) bên dưới biểu thị sự sai khiến bằng mệnh lệnh. Kết hợp hai yêu tố trên và dưới, cùng thể hiện một ý nghĩa: đấng minh quân là người dùng quyền uy sai khiến, trị vì thiên hạ, chỉ cần lên tiếng mà chưa cần ra tay. Đó là thứ quyền uy của người đức cao vọng trọng, đứng đầu muôn dân. “Trì trượng động khẩu giả, quân dã” (người cầm gậy, lên tiếng sai bảo chính là Quân vương) là cách định nghĩa ngắn gọn nhất mà cũng đầy đủ nhất về đấng quân vương.",
