    "lesson": 13,
    "page": 102,
    "jlpt": "N3-N2",
    "chi_tiet": "Theo lý giải của các chuyên gia ngôn ngữ chữ SĨ 士 trong kim văn là một chữ tượng hình, hình dung bộ phận sinh dục của con đực, cũng chính là dạng thể ban đầu của chữ MẪU 牡(con đực). Sau dùng để chỉ đặc trưng về giới của người đàn ông theo nguyên tắc giả tá. Khi có chiến tranh, những người đàn ông khỏe mạnh, cường tráng phần lớn đều ra trận. Do đó chữ SĨ thường đi với chữ TỐT 卒 (lính) trong từ sĩ tốt hay sĩ khí (khí thế của binh sĩ). Về sau, trong quân đội có chia ra làm các bậc như trung sĩ, thượng sĩ, hạ sĩ…tất cả các chữ này đều có liên quan đến ý nghĩa gốc ban đầu của chữ SĨ. Ngoài những nghĩa có liên quan đến quân sự chữ sĩ còn dùng để chỉ tầng lớp giữa, sau hàng khanh đại phu và trước thứ dân. Nói đến tứ dân trong xã hội cũ, người ta thường nhắc đến sĩ dân 士民, thương dân 商民 , nông dân 农民 và công dân 工民 trong đó SĨ đứng hàng đầu. Trong tiếng việt cũng có câu “nhất 370 Nhóm biên soạn: https://www.facebook.com/vuihocchuhan/ sĩ nhì nông”. Và như vậy chữ SĨ dùng để chỉ người có học thức, biết văn biết võ. Trong tiếng hán hiện đại chữ SĨ còn phát triển thành hậu tố chỉ những người có tri thức, có trình độ học vấn nhất định trong lĩnh vực nào đó như bác sĩ, tiến sĩ, học sĩ…",
