    "id": 619,
    "kanji": "相",
    "han_viet": "Tướng, Tương",
    "nghia": "Tướng mạo",
    "on": "ソウショウ",
    "kun": "あい",
    "lesson": 16,
    "page": 121,
    "jlpt": "N3-N2",
    "chi_tiet": "Chữ TƯỚNG 相 là một chữ hội ý kết cấu trái phải. Trong đó MỘC 木 là cây, MỤC 目 là mắt. Tính chất hội ý của hai bộ này là sự tái hiện sinh động tập quán sinh hoạt của người trung quốc xưa. Cách hiểu thứ nhất cho rằng, khi con người sinh sống dựa vào rừng cây, cây là lá chắn của họ. Người ta ẩn sau gốc cây to, dùng mắt quan sát, nếu có thức ăn và cảm giác an toàn thì tiếp tục tiến lên để giành lấy, nếu thấy kẻ thù thì ẩn mình để bảo toàn tính mạng. Lại có cách lý giải thứ hai cho rằng TƯỚNG 相 là sự thể hiện ngắn gọn nhất của con người khi đã biết dựa vào rừng, khai thác tài nguyên phục vụ đời sống. MUC 目 và MỘC 木 hợp lại với ý nghĩa con người với thị giác đo lường, đánh giá lựa chọn gỗ, khai thác gỗ để sử dụng cho mục đích của mình. 512 Nhóm biên soạn: https://www.facebook.com/vuihocchuhan/ Dù lý giải bằng cách nào chữ TƯỚNG 相 cũng phản ánh rõ nét mối quan hệ giữa con người với thiên nhiên, và đặc biệt thể hiện khả năng nhận thức thế giới, biết tranh thủ môi trướng sống phục vụ đời sống của mình. Chữ TƯỚNG 相 từ nghĩa là quan sát, phát triển thành nghĩa hình hài, tướng mạo, phụ tá. Từ đó có thêm âm đọc thứ hai là TƯƠNG biểu thị ý nghĩa quan hệ qua lại như trong các từ tương tác, tương phản, tương đồng,…",
