    "chi_tiet": "Chữ CHI 支 là một chữ hội ý kết cấu trên dưới, gồm phần trên là 十 thật chất đây là một biến thể của bộ THỦ 手, ở dưới là bộ HỰU 又 (cũng là chỉ tay). Trong giáp cốt, kim và triện văn chữ CHI 支 được viết có hình dạng giống như hai bàn tay đang hướng về nhau, bàn tay phía bên dưới hơi ngửa ra, như đang nhận một vật gì đó từ bàn tay phía trên. Tính chất hội ý của chữ chi thể hiện ý nghĩa ban đầu là bàn tay phía trên đưa cho bàn tay phía dưới. Theo thời gian, bàn tay phía trên, dưới đều được thay đổi , nó có cách viết giống như chữ THẬP và chữ HỰU và trở thành chữ CHI 支 như bây giờ. Tính chất biểu ý của hai bộ thủ vẫn được giữ nguyên, chữ CHI 支 Từ ý nghĩa là chi cho, cấp cho, phát triển thêm nghĩa chỉ các bộ phận được chi cấp như chi nhánh, chi phái.",
