    "chi_tiet": "Chữ Ái(愛) ý nghĩa là tình yêu, gồm bộ tâm (心) (con tim) và chữ thụ (受) (chịu đựng), tình yêu thương chính là sự chấp nhận và tình nguyện hi sinh. Tuy nhiên trong chữ giản thể ngày nay, chữ Ái này đã bị mất đi chữ tâm (trái tim). Trở thành tình cảm (tình yêu) hời hợt bên ngoài không có con tim. Trên thực tế trong quá trình chuyển giao sang thời kỳ hiện đại, Trung Quốc đã xảy ra một biến hóa lớn. Sau Cách mạng văn hóa, các giá trị truyền thống của nền văn minh Trung Hoa 5.000 năm đã bị bóp méo và thay thế một cách không thương tiếc. Điều đó cũng thể hiện ngay trong chính chữ Hán giản thể. Loại chữ hiện đại này đã làm mất đi các yếu tố tượng hình, ý nghĩa thâm sâu và cái đạo mà người xưa truyền lại. Trong khi chữ Hán phồn thể bao hàm tư tưởng và văn hóa truyền thống của Trung Hoa thì chữ giản thể lại không làm được như thế.",
