    "jlpt": "N3-N2",
    "chi_tiet": "Tinh thần cao thượng, tôn vinh cái đẹp, bảo vệ cái thiện, lấy uy sức mà phục người, gọi là VÕ 武. Về mặt cấu tạo, VÕ 武 là một chữ hội ý có kết cấu trái phải, chữ này gồm chữ CHỈ 止 là dừng lại và chữ QUA 戈 là ngọn giáo. Tính chất biểu ý của chữ 武 là dùng võ thuật để ngăn cấm điều bạo ngược, chỉnh đốn sự rối loạn, thôi việc can qua. VÕ 武 cùng với VĂN 文 là hai lĩnh vực mà các đấng mày râu thời xưa luôn phải chuyên tâm trau dồi,người ta vẫn hay nói “văn võ song toàn 文武雙全”chỉ những người tài giỏi trên nhiều lĩnh vực. Ngoài nghĩa chỉ môn võ thuật ra, 武 còn có nghĩa liên quan đến quân sự , thường được dùng với âm VŨ như trong các từ vũ trang, vũ khí. 530 Nhóm biên soạn: https://www.facebook.com/vuihocchuhan/ HÁN VIỆT vong , vô , vọng viển vông, xa vời, ngông, lung NGHĨA VIỆT 妄 tung, ẩu, sằng bậy,… DẠNG KHÁC PHIÊN ÂM wàng Kun: みだ-りに ÂM KUN/ON On: モウボウ cuồng vọng 狂妄• vọng tưởng TỪ GHÉP 妄想. Chữ Vọng 妄 cũng có nhiều điểm tương đồng giống chữ Manh 氓, chữ Vọng 妄 cũng là một chữ hội ý gồm bộ 亡 nghĩa là mất và bộ Nữ 女 (đàn bà, con gái), tính chất biểu ý của nó là chỉ người không có quê hương bản quán, không chịu sự quản chế ràng buộc của gia đình, của xã hội hành động bừa bãi theo bản năng. Từ đó Vọng 妄 phát triển thành nghĩa tùy tiện,bừa bãi, viển vông, hay cuồng loạn.",
