    "chi_tiet": "Chữ Tiến\\Tấn 進 nghĩa là tiến tới, tiến bộ,… Là một chữ hội ý được hợp bởi bộ Sước 辶 (đi, bay, chạy,..) và bộ Chuy 隹 (một loài chim đuôi ngắn, xem kim văn và triện văn sẽ thấy rõ hình ảnh một con chim đang bay). Hai bộ trên hợp lại ý chỉ loài chim đang bay, do đặc điểm của loài chim là không bay lùi được chỉ có bay tiến, cho nên chữ 進 mang nghĩa là tiến lên, tiến tới. Một số tài liệu sau này phân tích chữ chuy thực chất là chữ Giai 佳 (đẹp tốt, may mắn,..) được viết khác đi, vì thế chữ Tiến 進 mang hàm ý là tiến tới những điều tốt đẹp, hay nói cách khác đi, chỗ nào có những sự tốt lành thì người ta sẽ tìm đến. Trong chữ “Tiến” giản thể 进, bị mất chữ “Giai” 佳 – 465 Nhóm biên soạn: https://www.facebook.com/vuihocchuhan/ Tốt đẹp, thay bằng chữ Tỉnh, nghĩa là Tiến bất Giai: Bước tiếp sẽ không may mắn, mà là rơi xuống đáy giếng (Chữ Tỉnh 井: cái giếng). Điều này khiến nhiều người liên tưởng đến cuộc cách mạng Đại Nhảy Vọt do Mao Trạch Đông thực hiện làm chết 43 triệu người từ 1958 đến 1960. Những thay đổi không nên có này thực sự làm mất đi nội hàm thâm sâu của chữ hán. 466 Nhóm biên soạn: https://www.facebook.com/vuihocchuhan/ HÁN VIỆT Tiết 卩 NGHĨA VIỆT Bộ tiết (214) DẠNG KHÁC PHIÊN ÂM bù • jié Kun: わりふ ÂM KUN/ON On: セツ TỪ GHÉP Đóng vai trò bộ thủ tạo chữ. Chữ TIẾT 卩 là một chữ tượng hình mô tả một người đàn ông đang quỳ gối, 卩 có thể được coi là một biến thể của NHÂN 人 (người). Con người đầu hàng quyền lực bằng cách quỳ gối xuống, vì vậy 卩 có nghĩa là một bằng chứng đại diện cho sự cai trị và quyền lực ở Trung Quốc cổ đại, nhưng ý nghĩa như vậy đã được thay thế. Bây giờ chúng ta hiếm khi sử dụng 卩 như là chữ đơn, nó chỉ sử dụng là thành phần tạo chữ hán mới (một trong 214 bộ thủ).",
