    "page": 182,
    "jlpt": "N3-N2",
    "chi_tiet": "Chữ CHÂU 州 là một chữ tượng hình (cũng có thể coi là chữ hội ý), mô tả một dòng sông ( xuyên 巛)với một hòn đảo ở giữa, do đó, 州 có nghĩa là cồn đất giữa nước, bãi cù lao,… cũng dùng như chữ châu 洲. Ở Trung Quốc cổ đại, 州 là một khu vực hành chánh, ngày xưa chia đất ra từng khu, lấy núi sông làm mốc, gọi là “châu”. Như: “Tô Châu” 蘇州, “Gia Châu” 加州.",
