    "jlpt": "N3-N2",
    "chi_tiet": "Chữ TIẾT 節 là một chữ hình thanh kết cấu trên dưới. Trong đó, bộ TỨC 即 bên dưới đóng vai trò chỉ âm đọc, ở phía trên là một dạng khác của bộ TRÚC 竹 (tre) có nhiệm vụ chỉ ý nghĩa. Căn cứ vào tính chất, khoảng cách đều đặn giữa các đốt tre người ta đã tạo ra chữ 節 với ý nghĩa là chuẩn mực, điều độ như trong các thủ tiết, tiết tháo, thời tiết. Một khoảng thời gian từ 45 -50 phút dạy và học ở giảng đường được quy định là tiết học và từ tiết chuyển sang tiếng việt được đọc chệch là tết như trong các từ Tết Nguyên Đán, Tết Nguyên Tiêu, Tết Trung Thu.",
