    "chi_tiet": "Chữ TUYỀN 泉 trong giáp cốt văn miêu tả một dòng nước chảy ra từ bụng đá. Nghĩa gốc của 泉 là “nguồn nước”, cũng chỉ luôn nghĩa “mạch nước ngầm”. Hình thể chữ 泉 từ lệ thư trở về sau thay đổi khá nhiều, hình ảnh dòng nước được thể hiện bằng bộ THỦY 水 và hình ảnh núi đá được thể hiện giống như chữ BẠCH 白. Chữ 泉 bắt đầu từ lệ thư là một chữ hội ý.",
