    "lesson": 27,
    "page": 188,
    "jlpt": "N3-N2",
    "chi_tiet": "Nếu được định nghĩa là chữ hình thanh, chữ CHI 枝 được tạo bởi bộ MỘC 木 (cây) là bộ phận biểu ý, chữ CHI 支(chi cho) biểu thị âm đọc. Với bộ MỘC có nhiêm vụ tạo ý nghĩa liên quan đến cây cối, thực vật, Kết hợp với âm đọc của chữ CHI 支, có nghĩa là cành cây, nhánh cây. Cũng có thể hiểu CHI 枝 là chữ hội ý. Tính chất hội ý của hai bộ thủ tạo chữ là chỉ việc cây cung cấp chất dinh dưỡng cho các cành nhỏ. Chữ CHI 枝 cũng được dùng song song với chữ 支 hay 肢 với cùng ý nghĩa chỉ các bộ phận nhỏ được chia ra từ một bộ phận lớn hơn.",
