    "page": 194,
    "jlpt": "N3-N2",
    "chi_tiet": "Chữ DƯƠNG 陽 bên trái có bộ “Phụ” (阝) tức là núi đất, bên phải có chữ “Nhật” (日) đứng trên chữ “Nhất” (一), tạo thành hình ảnh mặt trời mọc. Bên dưới là chữ “Vật” (勿) mang ý nghĩa vạn sự vạn vật được mặt trời chiếu sáng. Chữ “Dương” (陽) thường đi liền với chữ “Âm” (陰) tạo thành hai mặt đối lập. Bởi có Dương và Âm, nên mới có sáng và tối, ngày và đêm, nóng và lạnh, thiện và ác, tốt và xấu, trong và đục… Từ Thái Cực mà sinh ra hai khí Âm Dương, Dương phát tán còn Âm thì tụ hội, cho nên Âm Dương bổ sung và tương trợ cho nhau, đặc tính trái ngược nhau nhưng không tương hại, tương khắc mà tương hòa, tương sinh mà tương diệt.",
