    "page": 194,
    "jlpt": "N3-N2",
    "chi_tiet": "Chữ TRIỆU 兆 mô tả hai người đàn ông chạy trốn khỏi dòng sông. Lũ lụt là thảm họa lớn ở Trung Quốc cổ đại, vì vậy khi dòng sông chảy mạnh hơn bình thường, mọi người sẽ biết đó là dấu hiệu của lũ lụt, vì vậy họ tìm cách thoát khỏi dòng sông. Nghĩa gốc ban đầu của 兆 là chạy trốn nhưng ý nghĩa như vậy đã được thay thế bằng đào 逃, nên 兆 chỉ còn có nghĩa là dấu hiệu cho thấy một cái gì đó sắp xảy ra (điềm, đời xưa dùng mai rùa bói, đốt mai rùa, rồi coi những đường nứt mà đoán tốt xấu gọi là triệu. Phàm dùng cái gì để xem tốt xấu đều gọi là triệu. Như cát triệu 吉兆 điềm tốt). Mặt khác, 兆 cũng đại diện cho một con số lớn, một triệu.",
