    "jlpt": "N3-N2",
    "chi_tiet": "Chữ SÁT 殺 là một chữ hội ý kiêm hình thanh. Thật ra, chỉ riêng chữ 杀 cũng đã có nghĩa là giết chết. Trong giáp cốt văn 杀 miêu tả một vật sắt nhọn xuyên qua đầu một con thú với cái đuôi rũ xuống, hình ảnh cái đuôi rũ xuống hàm ý con thú này đã chết. Từ chữ tiểu triện về sau, người ta thêm vào bộ THÙ 殳 (một loại vũ khí) để nhấn mạnh cái chết được gây ra bởi vũ lực. 367 Nhóm biên soạn: https://www.facebook.com/vuihocchuhan/ HÁN VIỆT Sâm Rừng rậm, sum suê, rậm rạp, NGHĨA VIỆT 森 đông đúc,… DẠNG KHÁC PHIÊN ÂM Sēn Kun: もり ÂM KUN/ON On: シン Tiêu sâm 蕭森 • sâm lâm 森 TỪ GHÉP 林 • sâm lâm học 森林學 Chữ Sâm 森 được tạo thành từ 3 bộ mộc 木 (cây cối) với ý nghĩa là rậm rạp, sum suê, hay đông đúc...Hầu hết các chữ được tạo thành từ 2 hoặc 3 bộ giống nhau là các chữ Hội ý (theo Lục thư) và thường là rất dễ nhớ (姦 gian, 轟 oanh...). “Một MỘC chỉ mới là cây Hai MỘC ghép lại trồng cây gây rừng Thêm MỘC ở phía lưng chừng Chữ SÂM rậm rạp khu rừng âm u”.",
