    "jlpt": "N3-N2",
    "chi_tiet": "Chữ VỊ 位 về mặt cấu tạo là một chữ hội ý kết cấu trái phải, được hợp bởi bộ NHÂN 亻(người) bên trái và bộ LẬP 立 (đứng) bên phải. Tính chất hội ý của hai bộ thủ này khi kết hợp lại với nhau là chỉ một người đang trong trạng thái đứng yên. Trong cấu tạo chữ VỊ 位 thì chữ LẬP 立 đóng vai trò biểu thị tư thế đứng của NHÂN 亻 (người), có thể nói người này đang đứng yên, không di chuyển và vị trí của người đó có thể xác định được. Vị trí của một người hay một vật chỉ được xác định chính xác khi người hoặc sự vật đó đứng yên. Chữ VỊ 位 từ nghĩa chỉ vị trí của sự vật phát triển thêm các nghĩa chỉ vị trí của một người trong một bộ máy nào đó như chức vị , tước vị. Ngoài ra cũng được dùng với nghĩa tôn kính như chư vị.",
