    "chi_tiet": "Chữ CHÍNH 政 là chữ hội ý kiêm hình thanh kết cấu trái phải, gồm hai bộ thủ là CHÍNH 正(ngay thẳng, đúng đắn) và PHỘC 攵(ngọn roi) tạo thành. Trước hết nói đến chữ CHÍNH 正. Chữ CHÍNH 正 bao gồm chữ CHỈ 止(dừng lại) và chữ NHẤT “—“ tạo thành. Chữ CHỈ 止 là một chữ tượng hình vẽ lại đôi chân đứng thẳng, hai bàn chân song song, khác với chữ TẨU 走 (chạy, đi) hình dung như chân trước, chân sau đang rảo bước. Chữ chính có nghĩa là cử chỉ , hành vi ngay thẳng, thống nhất, không thiên lệch. Những hành vi, lời nói tiền hậu bất nhất được coi là bất chính. Chữ NHẤT — trên đầu thể hiện chữ chính không chỉ là hành vi ngay thẳng, 72 Nhóm biên soạn: https://www.facebook.com/vuihocchuhan/ đúng đắn mà còn phải suy nghĩ đúng đắn, hành vi thống nhất với suy nghĩ. Bộ PHỘC 攵 là ngọn roi – biểu tượng của quyền uy, sự trừng phạt, sắc lệnh. Đó cũng là một loạt những bộ luật mà nhà nước ban hành nhằm hướng người dân đến tuân thủ chính đạo, xa rời tà đạo. Thiên vi chính trong luận ngữ có câu :” Đạo chi dĩ chính, tề chi dĩ hình, dân miễn chi vô sỉ; Đạo chi dĩ đức, tề chi dĩ lễ, hữu sỉ thả cách.” Nghĩa là quản lý dân bằng chính lệnh, khống chế dân bằng hình phạt, dân chúng có thể nhất thời không mắc tội nhưng họ không ý thức được việc phạm tội là sỉ nhục. Ngược lại , dùng đạo đức để giáo hóa dân chúng, dùng lễ giáo để ràng buộc họ vào quy phạm xã hội, dân chúng không những biết tự trọng mà còn biệt sủa chữa lỗi lầm.",
