    "jlpt": "N3-N2",
    "chi_tiet": "Chữ TRỊ 治 là một chữ hội ý kết cấu trái phải, gồm bộ thủy và một phần của chữ THAI 胎 (phôi thai) hợp thành. Với vai trò biểu nghĩa, chấm THỦY 氵 là biểu tượng của nước, thể hiện bản chất của vấn đề trị thủy. Trị thủy phải căn cứ vào tính chất của nước, khi nước lũ về , có khả năng sảy ra lũ lụt, người dân tiến hành phân lũ để tránh tức nước vỡ bờ. Từ việc trị thủy, người ta đến việc trị người phải lấy giáo dục, giáo hóa làm chính, làm cho con người từ chỗ có tri thức đén chỗ hiểu biết, nhận thức và phân biệt đúng sai. Giáo hóa chúng dân cũng là mấu chốt của việc thi hành nhân chính. Chữ THAI 治 có nghĩa là phôi thai, manh nha. Vai trò biểu ý của THAI 胎 trong chữ TRỊ 治 là biết căn nguyên, trị vì từ gốc. Muốn cho xã hội yên bình, con người sống ôn hòa với nhau thì mọi nguy cơ tội ác cần phải được ngăn chặn từ gốc. phòng bao giờ cũng hơn chữa, mà khi chữa thì phải chữa từ gốc.",
