    "chi_tiet": "Chữ BINH về cấu tạo là một chữ hội ý kết cấu trên dưới, bao gồm phía trên là bộ CÂN 斤 (cây rìu) và ở dưới là chữ CỦNG 廾 (đôi tay chắp lại). Tính chất biểu ý của chữ BINH là chỉ đôi tay đang cầm vũ khí. Trong kim văn và triện văn chữ BINH được viết dưới dạng đôi bàn tay đang cầm một thứ gì đó giống như xương thú, điều này cũng lý giải việc người xưa đã từng dùng xương thú làm vũ khí chiến đấu và săn bắn. Hình ảnh chiếc xương thú trong chữ BINH biến đổi dần và thay thế bằng chữ CÂN như ngày nay. Vậy tai sao đôi bàn tay cầm vũ khí lại thể hiện là một binh sĩ ?. Bởi lẽ người xưa quan niệm, còn sống là phải chiến đấu, phải cầm chắc vũ khí trong tay không được buông bỏ vũ khí. Người lính phải là người có bản lĩnh, dám đối chọi với kẻ thù, không chịu khuất phục hay đầu hàng.",
